-- OPTIONAL: only missing basis tables; review existing schema first.
CREATE TABLE SIDDA.LEGAL_BASIS_HEAD_A (link_id VARCHAR2(64) PRIMARY KEY, team_id VARCHAR2(256) NOT NULL, revision NUMBER(19) NOT NULL);
CREATE TABLE SIDDA.LEGAL_BASIS_REVISION_A (link_id VARCHAR2(64), revision NUMBER(19), payload CLOB NOT NULL, hash VARCHAR2(64) NOT NULL, PRIMARY KEY(link_id,revision));
CREATE TABLE SIDDA.LEGAL_BASIS_BINDING_A (binding_id VARCHAR2(64) PRIMARY KEY, link_id VARCHAR2(64), revision NUMBER(19), generation VARCHAR2(512), payload CLOB NOT NULL, hash VARCHAR2(64) NOT NULL, UNIQUE(link_id,revision,generation));
CREATE TABLE SIDDA.LEGAL_BASIS_EVENT_A (event_id VARCHAR2(64) PRIMARY KEY, link_id VARCHAR2(64), payload CLOB NOT NULL, hash VARCHAR2(64) NOT NULL);
CREATE TABLE SIDDA.LEGAL_BASIS_RECEIPT_A (receipt_id VARCHAR2(128) PRIMARY KEY, input_hash VARCHAR2(64) NOT NULL, payload CLOB NOT NULL, hash VARCHAR2(64) NOT NULL);
CREATE TABLE SIDDA.LEGAL_BASIS_LINEAGE_A (version_id VARCHAR2(512) PRIMARY KEY, family_id VARCHAR2(512), payload CLOB NOT NULL, hash VARCHAR2(64) NOT NULL);
CREATE TABLE SIDDA.LEGAL_BASIS_MIGRATION_A (migration_id VARCHAR2(64) PRIMARY KEY, payload CLOB NOT NULL, hash VARCHAR2(64) NOT NULL);
CREATE TABLE SIDDA.LEGAL_BASIS_VIEW_HEAD_A (session_key VARCHAR2(64) PRIMARY KEY, payload CLOB NOT NULL, hash VARCHAR2(64) NOT NULL);
